2154: {
2155: 	u16 curr_session = l->peer_session;
2156: 	u16 session = msg_session(hdr);
2157: 	int mtyp = msg_type(hdr);
2158: 
2159: 	if (msg_user(hdr) != LINK_PROTOCOL)
