2181: 			return false;
2182: 		if (!(l->peer_caps & TIPC_LINK_PROTO_SEQNO))
2183: 			return true;
2184: 		/* Accept only STATE with new sequence number */
2185: 		return !less(msg_seqno(hdr), l->rcv_nxt_state);
2186: 	default:
2187: 		return false;
2188: 	}
2189: }
