2348: static bool tipc_link_build_bc_proto_msg(struct tipc_link *l, bool bcast,
2349: 					 u16 peers_snd_nxt,
2350: 					 struct sk_buff_head *xmitq)
2351: {
2352: 	struct sk_buff *skb;
2353: 	struct tipc_msg *hdr;
2354: 	struct sk_buff *dfrd_skb = skb_peek(&l->deferdq);
2355: 	u16 ack = l->rcv_nxt - 1;
2356: 	u16 gap_to = peers_snd_nxt - 1;
2357: 
2358: 	skb = tipc_msg_create(BCAST_PROTOCOL, STATE_MSG, INT_H_SIZE,
2359: 			      0, l->addr, tipc_own_addr(l->net), 0, 0, 0);
2360: 	if (!skb)
2361: 		return false;
2362: 	hdr = buf_msg(skb);
2363: 	msg_set_last_bcast(hdr, l->bc_sndlink->snd_nxt - 1);
2364: 	msg_set_bcast_ack(hdr, ack);
2365: 	msg_set_bcgap_after(hdr, ack);
2366: 	if (dfrd_skb)
2367: 		gap_to = buf_seqno(dfrd_skb) - 1;
2368: 	msg_set_bcgap_to(hdr, gap_to);
2369: 	msg_set_non_seq(hdr, bcast);
2370: 	__skb_queue_tail(xmitq, skb);
2371: 	return true;
2372: }
